import{I as e,L as t,O as n,j as r,k as i,t as a}from"./app-DO0QAytN.js";var o=JSON.parse(`{"path":"/interview/agent-interview/react.html","title":"ReAct 是什么？","lang":"zh-CN","frontmatter":{"title":"ReAct 是什么？","icon":"mdi:brain","tag":["Agent面试","ReAct","思考行动"],"description":"ReAct 是什么？Thought、Action、Observation 分别代表什么？ 这道面试题考的是 ReAct 推理框架，是大模型 Agent 开发中最核心的推理范式之一。简单说，ReAct 就是让大模型在解决问题时&quot;边想边做、边做边想&quot;，通过 Thought（思考）、Action（行动）、Observation（观察）三个...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"ReAct 是什么？\\",\\"image\\":[\\"https://www.anyiai.cc/images/agent-interview/react_cover.png\\",\\"https://www.anyiai.cc/images/agent-interview/20260608_213352_002624_01.png\\",\\"https://www.anyiai.cc/images/agent-interview/20260608_213346_821568_01.png\\",\\"https://www.anyiai.cc/images/agent-interview/20260608_213344_125696_01.png\\",\\"https://www.anyiai.cc/images/agent-interview/20260608_213414_869440_01.png\\"],\\"dateModified\\":\\"2026-10-28T04:17:51.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"安逸Ai\\"}]}"],["meta",{"property":"og:url","content":"https://www.anyiai.cc/interview/agent-interview/react.html"}],["meta",{"property":"og:site_name","content":"AI 学习资源站"}],["meta",{"property":"og:title","content":"ReAct 是什么？"}],["meta",{"property":"og:description","content":"ReAct 是什么？Thought、Action、Observation 分别代表什么？ 这道面试题考的是 ReAct 推理框架，是大模型 Agent 开发中最核心的推理范式之一。简单说，ReAct 就是让大模型在解决问题时&quot;边想边做、边做边想&quot;，通过 Thought（思考）、Action（行动）、Observation（观察）三个..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://www.anyiai.cc/images/agent-interview/react_cover.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-28T04:17:51.000Z"}],["meta",{"property":"article:tag","content":"思考行动"}],["meta",{"property":"article:tag","content":"ReAct"}],["meta",{"property":"article:tag","content":"Agent面试"}],["meta",{"property":"article:modified_time","content":"2026-10-28T04:17:51.000Z"}],["link",{"rel":"canonical","href":"https://www.anyiai.cc/interview/agent-interview/react.html"}]]},"git":{"createdTime":1793161071000,"updatedTime":1793161071000,"contributors":[{"name":"anyi","username":"anyi","email":"1961741003@qq.com","commits":1,"url":"https://github.com/anyi"}]},"readingTime":{"minutes":5.78,"words":1734},"filePathRelative":"interview/agent-interview/react.md","autoDesc":true}`),s={name:`react.md`};function c(a,o,s,c,l,u){let d=t(`ReadMoreLock`);return e(),n(`div`,null,[o[0]||=i(`<figure><img src="/images/agent-interview/react_cover.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h1 id="react-是什么-thought、action、observation-分别代表什么" tabindex="-1"><a class="header-anchor" href="#react-是什么-thought、action、observation-分别代表什么"><span>ReAct 是什么？Thought、Action、Observation 分别代表什么？</span></a></h1><p>这道面试题考的是 <strong>ReAct 推理框架</strong>，是大模型 Agent 开发中最核心的推理范式之一。简单说，ReAct 就是让大模型在解决问题时&quot;边想边做、边做边想&quot;，通过 Thought（思考）、Action（行动）、Observation（观察）三个步骤的循环迭代，最终完成任务。</p><hr><h2 id="板块1-react-解决的核心问题——为什么需要-推理-行动" tabindex="-1"><a class="header-anchor" href="#板块1-react-解决的核心问题——为什么需要-推理-行动"><span>板块1：ReAct 解决的核心问题——为什么需要&quot;推理+行动&quot;</span></a></h2><p>先说背景。早期大模型处理复杂任务，走的是两条路：</p><p><strong>纯推理路线</strong>（CoT思维链）：模型只管想，从头到尾靠内部推理得出答案。问题在哪？模型&quot;闭门造车&quot;，不跟外部世界交互，遇到不知道的信息就瞎编，幻觉问题严重。</p><p><strong>纯行动路线</strong>（WebGPT、SayCan）：模型直接调用工具查资料、执行操作。问题在哪？模型&quot;只干不想&quot;，拿到什么查什么，没有规划，走一步算一步，经常做无用功。</p><p>ReAct 的出现，就是为了解决这两条路的缺陷。它的核心思想很简单：<strong>交替进行推理和行动，让思考指导行动，让行动验证思考</strong>。</p><figure><img src="/images/agent-interview/20260608_213352_002624_01.png" alt="三列对比图：纯推理路线只思考不行动、纯行动路线只行动不思考、ReAct路线边思考边行动" tabindex="0" loading="lazy"><figcaption>三列对比图：纯推理路线只思考不行动、纯行动路线只行动不思考、ReAct路线边思考边行动</figcaption></figure><p>你可以把大模型想象成一个需要完成复杂任务的员工：</p><ul><li>纯推理型员工 → 纸上谈兵，方案写得漂亮但不一定能用</li><li>纯行动型员工 → 蛮干硬拼，累死累活可能方向就错了</li><li>ReAct 型员工 → 先想后做、边做边想，遇到问题随时调整</li></ul><hr>`,13),r(d),o[1]||=i(`<h2 id="板块2-三元组各司其职——thought、action、observation-的定义" tabindex="-1"><a class="header-anchor" href="#板块2-三元组各司其职——thought、action、observation-的定义"><span>板块2：三元组各司其职——Thought、Action、Observation 的定义</span></a></h2><p>ReAct 的核心就是 <strong>Thought → Action → Observation</strong> 三个环节不断循环。咱们逐个说：</p><h3 id="thought-思考" tabindex="-1"><a class="header-anchor" href="#thought-思考"><span>Thought（思考）</span></a></h3><p>这是模型的&quot;内心独白&quot;。Thought 负责：</p><ul><li>分解任务：把大目标拆成小步骤</li><li>分析进度：判断当前做到哪一步了</li><li>决定策略：下一步该怎么做</li></ul><p><strong>关键点</strong>：Thought 只在模型内部流转，不会发到外部工具。它是纯推理过程。</p><h3 id="action-行动" tabindex="-1"><a class="header-anchor" href="#action-行动"><span>Action（行动）</span></a></h3><p>这是模型的&quot;外部接口&quot;。Thought 想清楚之后，Action 负责：</p><ul><li>调用搜索引擎查资料</li><li>调用 API 获取信息</li><li>执行某个具体操作</li></ul><p><strong>关键点</strong>：Action 是模型与外部世界的交互通道，它会把指令发送给外部工具。</p><h3 id="observation-观察" tabindex="-1"><a class="header-anchor" href="#observation-观察"><span>Observation（观察）</span></a></h3><p>这是外部世界的&quot;真实反馈&quot;。Action 执行完后，Observation 返回：</p><ul><li>搜索结果</li><li>API 返回的数据</li><li>操作的实际结果</li></ul><p><strong>关键点</strong>：Observation 保证模型是基于真实信息推理，而不是凭空想象。</p><figure><img src="/images/agent-interview/20260608_213346_821568_01.png" alt="三元组关系示意图，Thought内心独白指向Action外部行动，Action结果返回为Observation真实反馈，三者形成闭环" tabindex="0" loading="lazy"><figcaption>三元组关系示意图，Thought内心独白指向Action外部行动，Action结果返回为Observation真实反馈，三者形成闭环</figcaption></figure><p>用一个场景来理解：医生看病。</p><ul><li><strong>Thought</strong>：医生思考&quot;这个症状可能是什么病，需要做哪些检查&quot;</li><li><strong>Action</strong>：医生开出检查单，让病人去做检查</li><li><strong>Observation</strong>：检查报告出来了，这是真实的客观数据</li></ul><p>然后医生再根据检查结果继续思考、继续开检查或开药，这就是一个完整的循环。</p><hr><h2 id="板块3-循环工作机制——react-如何迭代完成任务" tabindex="-1"><a class="header-anchor" href="#板块3-循环工作机制——react-如何迭代完成任务"><span>板块3：循环工作机制——ReAct 如何迭代完成任务</span></a></h2><p>单个 Thought-Action-Observation 只是一个基本单元。ReAct 的真正威力在于<strong>循环迭代</strong>。</p><p>整个流程是这样的：</p><ol><li>模型根据当前状态输出 <strong>Thought</strong></li><li>Thought 决定需要执行什么 <strong>Action</strong></li><li>Action 调用外部工具，返回 <strong>Observation</strong></li><li>Observation 作为下一轮的输入，触发新的 <strong>Thought</strong></li><li>循环往复，直到模型认为&quot;可以输出答案了&quot;，输出 <strong>Final Answer</strong></li></ol><figure><img src="/images/agent-interview/20260608_213344_125696_01.png" alt="ReAct循环流程图，展示Thought→Action→Observation→新Thought...→Final Answer的多轮迭代过程" tabindex="0" loading="lazy"><figcaption>ReAct循环流程图，展示Thought→Action→Observation→新Thought...→Final Answer的多轮迭代过程</figcaption></figure><p>这就好比用导航开车：</p><ul><li>纯推理模式：出发前规划好全程路线，然后闭着眼睛开</li><li>ReAct 模式：导航每过一段路就播报&quot;你当前位置如何、前方怎么走&quot;，实时调整</li></ul><p>每一步的 Observation 都在纠正模型的推理，让后续思考越来越准确。这也是 ReAct 能显著<strong>减少幻觉</strong>的原因——你的每一步推理都有真实数据做锚点。</p><p>在工程实现上，<strong>LangChain 的 AgentExecutor</strong> 就是 ReAct 的典型实现。它维护一个循环，不断调用 agent 生成 Thought 和 Action，执行后获取 Observation，直到 agent 输出 Final Answer。</p><hr><h2 id="板块4-优势、局限与实际应用" tabindex="-1"><a class="header-anchor" href="#板块4-优势、局限与实际应用"><span>板块4：优势、局限与实际应用</span></a></h2><h3 id="优势" tabindex="-1"><a class="header-anchor" href="#优势"><span>优势</span></a></h3><ul><li><strong>可解释性强</strong>：你能看到模型每一步在想什么、做了什么、结果是什么</li><li><strong>减少幻觉</strong>：每步推理都基于真实的 Observation，不再凭空编造</li><li><strong>泛化性好</strong>：同一套框架，换个工具就能处理不同任务</li></ul><h3 id="局限" tabindex="-1"><a class="header-anchor" href="#局限"><span>局限</span></a></h3><ul><li><strong>计算开销大</strong>：多轮循环意味着多次 LLM 调用，成本高、延迟高</li><li><strong>错误传播</strong>：某一轮推理错了，后面的结论可能全歪</li><li><strong>依赖模型能力</strong>：模型本身不够强，Thought 的质量就不行，整个链条都会受影响</li></ul><figure><img src="/images/agent-interview/20260608_213414_869440_01.png" alt="优劣势对比图，左侧优势（可解释、减少幻觉、泛化）、右侧局限（开销、错误传播、能力依赖）" tabindex="0" loading="lazy"><figcaption>优劣势对比图，左侧优势（可解释、减少幻觉、泛化）、右侧局限（开销、错误传播、能力依赖）</figcaption></figure><h3 id="应用场景" tabindex="-1"><a class="header-anchor" href="#应用场景"><span>应用场景</span></a></h3><p>ReAct 是当前主流 Agent 框架的底层推理模式：</p><ul><li><strong>LangChain Agent</strong>：用 AgentExecutor 实现 ReAct 循环</li><li><strong>LlamaIndex Agent</strong>：同样基于 ReAct 范式</li><li><strong>AutoGPT 等项目</strong>：本质就是 ReAct 的工程实现</li></ul><p>这把&quot;瑞士军刀&quot;很好用，但也要看任务场景——简单的问答用 CoT 就够了，复杂的工具调用任务才需要 ReAct。</p><hr><h2 id="面试怎么答" tabindex="-1"><a class="header-anchor" href="#面试怎么答"><span>面试怎么答</span></a></h2><h3 id="基础版" tabindex="-1"><a class="header-anchor" href="#基础版"><span>基础版</span></a></h3><p>ReAct 全称是 Reasoning and Acting，是一种让大模型&quot;边推理边行动&quot;的推理框架。它通过 Thought-Action-Observation 三个环节的循环迭代来处理复杂任务：Thought 是模型的内心独白，负责分解任务和规划策略；Action 是外部接口，调用工具获取信息；Observation 是真实反馈，保证推理基于事实数据。这个循环持续进行，直到模型输出最终答案。LangChain 的 AgentExecutor 就是 ReAct 的典型实现。</p><h3 id="加分版" tabindex="-1"><a class="header-anchor" href="#加分版"><span>加分版</span></a></h3><p>相比纯推理的 CoT，ReAct 的核心优势在于引入了真实世界的反馈，能有效减少幻觉。相比纯行动的 WebGPT，ReAct 通过 Thought 保持了推理的可控性和方向感。ReAct 也有不少改进变体，比如 Reflexion（加入自我反思）、Plan-and-Execute（先规划再执行）。在实际开发中，ReAct 是 LangChain、LlamaIndex 等主流 Agent 框架的底层推理模式，适用于需要多步工具调用的复杂场景。</p><hr><h2 id="一句话总结" tabindex="-1"><a class="header-anchor" href="#一句话总结"><span>一句话总结</span></a></h2><p>ReAct 就是让大模型通过&quot;想清楚 → 做一下 → 看结果 → 再想清楚&quot;的循环，在推理和行动交替中完成复杂任务。</p>`,48)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};